<?php /** @var array $byDept @var array $gaps */ ?>
<div class="page-head"><div><h1><?= icon('file') ?> <?= e(t('bia.report')) ?></h1><p class="sub"><?= e(t('bia.report_hint')) ?></p></div><div class="actions noprint"><a class="btn secondary" href="<?= e(url('bia')) ?>"><?= e(t('common.back')) ?></a><button class="btn" type="button" data-print><?= e(t('common.print')) ?></button></div></div>
<section class="card"><h2><?= e(t('bia.by_department')) ?></h2><div class="table-wrap"><table class="data"><thead><tr><th><?= e(t('bia.department')) ?></th><th class="num"><?= e(t('bia.stat_total')) ?></th><th class="num"><?= e(t('bia.stat_critical')) ?></th><th class="num"><?= e(t('enum.bstatus.approved')) ?></th></tr></thead><tbody>
<?php if (!$byDept): ?><tr><td colspan="4" class="empty"><?= e(t('common.no_results')) ?></td></tr><?php endif; ?>
<?php foreach ($byDept as $d): ?><tr><td><?= e(lname($d)) ?></td><td class="num"><?= (int)$d['total'] ?></td><td class="num"><?= (int)$d['crit'] ?></td><td class="num"><?= (int)$d['approved'] ?></td></tr><?php endforeach; ?></tbody></table></div></section>
<section class="card"><h2><?= e(t('bia.gaps_title')) ?></h2>
<?php if (!$gaps): ?><p class="empty"><?= e(t('bia.no_gaps')) ?></p><?php else: ?><ul class="task-list"><?php foreach ($gaps as $g): ?><li><a href="<?= e(url('bia/' . $g['process']['id'])) ?>"><?= e($g['process']['code'] . ' — ' . $g['process']['name']) ?></a><span class="muted"><?= e(t('bia.gap_' . $g['kind'], ['system' => $g['system'], 'have' => $g['have'], 'need' => $g['need']])) ?></span></li><?php endforeach; ?></ul><?php endif; ?></section>
